vulnerable_code:
package backups

import (
	"context"
	"myapp/db"
	"myapp/export"
)

type SnapshotJob struct {
	TenantID        string
	SnapshotID      string
	TargetExportURI string
}

type BackupDispatcher struct {
	DB     db.SnapshotStore
	Export export.Service
}

func (d *BackupDispatcher) RunSnapshotExport(ctx context.Context, job SnapshotJob) error {
	// BOLA: Worker reads database snapshot directly by SnapshotID without verifying
	// that the snapshot belongs to TenantID.
	snapData, err := d.DB.ReadSnapshotArchive(ctx, job.SnapshotID)
	if err != nil {
		return err
	}

	return d.Export.WriteToStorage(ctx, job.TargetExportURI, snapData)
}

corrected_code:
package backups

import (
	"context"
	"errors"
	"myapp/db"
	"myapp/export"
)

type SnapshotJob struct {
	TenantID        string
	SnapshotID      string
	TargetExportURI string
}

type BackupDispatcher struct {
	DB     db.SnapshotStore
	Export export.Service
}

func (d *BackupDispatcher) RunSnapshotExport(ctx context.Context, job SnapshotJob) error {
	snapOwner, err := d.DB.GetSnapshotTenant(ctx, job.SnapshotID)
	if err != nil || snapOwner != job.TenantID {
		return errors.New("snapshot export rejected: snapshot does not belong to tenant")
	}

	snapData, err := d.DB.ReadSnapshotArchive(ctx, job.SnapshotID)
	if err != nil {
		return err
	}

	return d.Export.WriteToStorage(ctx, job.TargetExportURI, snapData)
}
